# 1. تعريف دالة آمنة ونظيفة لحساب متوسط الأعداد في قائمة
def calculate_average(numbers_list):
    # 2. التحقق من أن القائمة ليست فارغة لتفادي خطأ القسمة على صفر
    if not numbers_list:
        # 3. إرجاع القيمة صفر في حال كانت القائمة فارغة
        return 0.0
    # 4. حساب مجموع العناصر وتقسيمها على العدد الإجمالي بأمان
    return sum(numbers_list) / len(numbers_list)

